"""Dependency-free Ingress UI using the ACP/AEP visual language."""

ADMIN_CSS = r"""
:root{color-scheme:light;scrollbar-gutter:stable;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--cyan:#058caf;--cyan-soft:#dff5fa;--good:#16845b;--danger:#c43f55;--shadow:0 5px 22px #1e3a5f12}html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--cyan:#52c9e6;--cyan-soft:#173b4a;--good:#50c895;--danger:#ff8798;--shadow:none}*{box-sizing:border-box}[hidden]{display:none!important}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}body.drawer-open{overflow:hidden}.app{max-width:1840px;margin:auto;padding:22px clamp(18px,2.8vw,48px) 40px}.site-header{margin-bottom:28px}.header-main{display:flex;align-items:center;gap:20px;min-height:58px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand b{font-size:13px;color:var(--muted);font-weight:650;white-space:nowrap}.header-actions{display:flex;gap:8px;margin-left:auto}.switch,.secondary,.danger{color:var(--text);padding:9px 12px;border-radius:7px;border:1px solid var(--line);background:var(--surface);font:inherit;cursor:pointer}.danger{color:var(--danger);border-color:color-mix(in srgb,var(--danger) 40%,transparent)}button:disabled{opacity:.45;cursor:not-allowed}.nav-scroll{margin-top:12px;overflow-x:auto}.nav{display:flex;gap:5px;width:max-content;min-width:100%}.nav a{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px}.nav a.active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.view{display:none}.view.active{display:block}.pagehead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:4px 0 20px}.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.pagehead p,.card p{margin:0;color:var(--muted);line-height:1.55}.primary{color:#fff;background:var(--cyan);padding:10px 14px;border-radius:7px;border:0;font:inherit;font-weight:700;white-space:nowrap;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px}.card,.metric,.item-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric strong{display:block;font-size:25px;line-height:1.2}.metric span{display:block;color:var(--muted);margin-top:5px}.notice{margin-top:16px}.notice h2,.item-card h2{font-size:19px;margin:0 0 7px}.state{display:inline-flex;align-items:center;gap:8px;color:var(--good);font-weight:700}.state:before{content:"";width:9px;height:9px;border-radius:50%;background:currentColor}.state.revoked,.state.archived{color:var(--danger)}.card-list{display:grid;gap:12px}.item-card{display:flex;align-items:center;justify-content:space-between;gap:20px}.item-card .meta{color:var(--muted);font:12px ui-monospace,SFMono-Regular,Consolas,monospace}.actions{display:flex;gap:7px;flex-wrap:wrap}.filter{display:block;margin:-8px 0 16px;color:var(--muted)}.empty{text-align:center;color:var(--muted);padding:32px}.drawer-shell{position:fixed;inset:0;z-index:1000}.drawer-overlay{position:absolute;inset:0;background:#07132180;backdrop-filter:blur(2px)}.drawer{position:absolute;inset:0 0 0 auto;width:min(520px,calc(100vw - 36px));background:var(--surface);border-left:1px solid var(--line);box-shadow:-18px 0 45px #07132135;display:flex;flex-direction:column;outline:0}.drawer-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:22px 24px;border-bottom:1px solid var(--line)}.drawer-head h2{margin:0;font-size:22px}.drawer-close{font-size:22px;line-height:1;padding:8px 11px}.drawer-body{padding:24px;overflow:auto}.drawer-body dl{display:grid;grid-template-columns:auto 1fr;gap:10px 16px}.drawer-body dt{font-weight:700}.drawer-body dd{margin:0;color:var(--muted)}.form-grid{display:grid;gap:15px}.form-grid label{font-weight:650}.form-grid input{display:block;width:100%;margin-top:6px;padding:10px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px}.warning{padding:12px;background:#fff5df;color:#76520f;border-radius:7px}.message{color:var(--danger);min-height:1.2em}.credential{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface2);border:1px solid var(--line);border-radius:8px;padding:14px;user-select:all}
@media(max-width:850px){.app{padding:16px}.nav-scroll{margin-inline:-16px;padding-inline:16px}.metrics{grid-template-columns:1fr}.pagehead{align-items:flex-start;flex-direction:column}.item-card{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.brand{font-size:19px}.brand img{width:40px;height:40px}.header-main{align-items:flex-start}.header-actions{flex-direction:column}.pagehead h1{font-size:25px}.drawer{width:100vw}.drawer-body dl{grid-template-columns:1fr;gap:4px}.drawer-body dd{margin-bottom:8px}}
"""

ADMIN_CSS += r"""
.form-grid textarea,.form-grid select{display:block;width:100%;margin-top:6px;padding:10px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px;font:inherit}.form-grid textarea{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:13px;resize:vertical}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:var(--cyan-soft);color:var(--cyan);font-size:12px;font-weight:700}.badge.danger{background:color-mix(in srgb,var(--danger) 12%,transparent);color:var(--danger);border:0}.details{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;color:var(--muted);font-size:13px;margin-top:8px}.details b{color:var(--text)}
"""

